/**
 * The notes chapter index and per-chapter loading, for code that must not import the corpus.
 *
 * WHY (TECH_DEBT_SPEC.md 2.2 part 2, measured 2026-11-05): lib/notes/chapters.ts imports every
 * chapter's `_data` (3,062 modules). NotesChapterLanding reached it through keepGoing.ts and
 * formula/chapterPages.ts, so every /notes route carried the whole corpus. This module reads the
 * GENERATED index (no content) and loads one chapter on demand.
 *
 * Generated by `npm run notes:chapter-loaders`; the builder is chapterIndexBuild.ts; drift check
 * tests/notes-chapter-loaders.test.ts; graph guard tests/notes-routes-lean-graph.test.ts.
 */
import type { NotesChapterRegistration } from "./chapters";
import type { FormulaPageCounts } from "@/lib/formula/chapterPages";
import { NOTES_CHAPTER_INDEX, NOTES_CHAPTER_LOADERS } from "./chapterLoaders.generated";
import { inBookOrder } from "./bookOrder";

/** A registry entry without its content, plus what callers read from that content. */
export type NotesChapterMeta = Omit<NotesChapterRegistration, "chapter" | "notes" | "slugs"> & {
  slugs: string[];
  chapterName: string;
  formulaCounts: FormulaPageCounts;
};

export { NOTES_CHAPTER_INDEX };

export function notesChapterMeta(subjectRoute: string, chapterSlug: string): NotesChapterMeta | null {
  return NOTES_CHAPTER_INDEX.find((c) => c.subjectRoute === subjectRoute && c.chapterSlug === chapterSlug) ?? null;
}

/** A subject's chapters in reading order, as getNotesChaptersForSubject orders them. */
export function notesChapterMetasForSubject(subjectRoute: string): NotesChapterMeta[] {
  return inBookOrder(NOTES_CHAPTER_INDEX.filter((c) => c.subjectRoute === subjectRoute));
}

/** One chapter's full registry entry, loading only its own `_data`. Null when unregistered. */
export async function loadNotesChapter(subjectRoute: string, chapterSlug: string): Promise<NotesChapterRegistration | null> {
  const meta = notesChapterMeta(subjectRoute, chapterSlug);
  const load = NOTES_CHAPTER_LOADERS[`${subjectRoute}/${chapterSlug}`];
  if (!meta || !load) return null;
  const { chapter, notes } = await load();
  const { chapterName, formulaCounts, ...rest } = meta;
  void chapterName;
  void formulaCounts;
  return { ...rest, chapter, notes, slugs: meta.slugs };
}
